create table tenants (id uuid primary key, name varchar(120) not null unique, status varchar(20) not null, rate_limit_per_second integer not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table app_users (id uuid primary key, external_id varchar(120) not null unique, tenant_id uuid, role varchar(30) not null);
create table templates (id uuid primary key, tenant_id uuid not null, name varchar(100) not null, channel varchar(20) not null, subject varchar(200), body text not null, version integer not null, active boolean not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint uk_template_tenant_name_channel unique(tenant_id,name,channel), constraint fk_template_tenant foreign key(tenant_id) references tenants(id));
create table channel_configs (id uuid primary key, tenant_id uuid not null, channel varchar(20) not null, enabled boolean not null, config_json text, updated_at timestamp with time zone not null, constraint uk_channel_config_tenant_type unique(tenant_id,channel), constraint fk_channel_config_tenant foreign key(tenant_id) references tenants(id));
create table notifications (id uuid primary key, tenant_id uuid not null, template_id uuid not null, channel varchar(20) not null, recipient varchar(320) not null, variables_json text not null, idempotency_key varchar(100) not null, status varchar(30) not null, scheduled_at timestamp with time zone, next_attempt_at timestamp with time zone, attempt_count integer not null, version bigint not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, constraint uk_notification_idempotency unique(tenant_id,idempotency_key), constraint fk_notification_tenant foreign key(tenant_id) references tenants(id), constraint fk_notification_template foreign key(template_id) references templates(id));
create index idx_notification_status_next on notifications(status,next_attempt_at); create index idx_notification_status_scheduled on notifications(status,scheduled_at); create index idx_notification_tenant_status on notifications(tenant_id,status); create index idx_notification_tenant_created on notifications(tenant_id,created_at);
create table delivery_attempts (id uuid primary key, notification_id uuid not null, attempt_number integer not null, status varchar(30) not null, provider_response text, error_code varchar(80), error_message text, started_at timestamp with time zone not null, completed_at timestamp with time zone not null, constraint fk_attempt_notification foreign key(notification_id) references notifications(id));
create index idx_attempt_notification on delivery_attempts(notification_id,attempt_number);
create table audit_events (id uuid primary key, tenant_id uuid not null, notification_id uuid, event_type varchar(30) not null, old_state varchar(30), new_state varchar(30), metadata text, created_at timestamp with time zone not null, constraint fk_audit_tenant foreign key(tenant_id) references tenants(id));
create index idx_audit_notification_time on audit_events(notification_id,created_at); create index idx_audit_tenant_time on audit_events(tenant_id,created_at);
